function Q4(n){const KS=ALL.map(x=>x[0]);return SH(W.filter(w=>[...w[0]].some(c=>KX[c]))).slice(0,n).map(([k,r,m])=>{const c=[...k],ix=c.map((x,i)=>KX[x]?i:-1).filter(i=>i>=0),i=R(ix),a=c[i];c[i]='＿';return{p:'Kanji apa yang hilang? Arti: '+m+' ('+r+')',big:c.join(''),a,note:k+' = '+r+' ('+m+')',o:uniq(a,()=>R(KS))}})}
