function Q7(n){const KS=ALL.map(x=>x[0]);return SH(SENT.filter(t=>[...t[0]].some(c=>KX[c]))).slice(0,n).map(([k,r,m])=>{const c=[...k],i=R(c.map((x,j)=>KX[x]?j:-1).filter(j=>j>=0)),a=c[i];c[i]='＿';return{p:'Kanji apa yang hilang? Arti: '+m,big:c.join(''),a,note:k+' = '+r+' ('+m+')',o:uniq(a,()=>R(KS))}})}
function Q8(n){return Array.from({length:n},()=>{const g=[...R(SIM)],x=KX[R(g)],s=new Set(g);while(s.size<4)s.add(R(ALL)[0]);return{p:'Pilih kanji yang tepat. Hati-hati, bentuknya mirip',big:x[2],a:x[0],ch:x[0],note:'Bacaan: '+x[1],o:SH([...s])}})}
function Q6(n){return SH(SENT).slice(0,n).map(([k,r,m])=>({p:'Apa arti kalimat ini?',big:k,a:m,rb:r,note:'Bacaan: '+r,say:k,o:uniq(m,()=>R(SENT)[2])}))}
