/* Mesin soal */
/* ===== Kanji baru: kanji yang pertama kali muncul di soal disorot kuning + romaji & cara baca, sekali saja ===== */
function kanjiBaru(q){
  const fc=document.querySelector('.fc'); if(!fc||!q||!q.big) return;
  const seen=new Set(S.seen||[]);
  const news=[...new Set([...q.big].filter(c=>KX[c]&&!seen.has(c)))];
  if(!news.length) return;
  const w=document.createTreeWalker(fc,NodeFilter.SHOW_TEXT),nodes=[];
  while(w.nextNode()) nodes.push(w.currentNode);
  nodes.forEach(t=>{
    if(![...t.data].some(c=>news.includes(c))) return;
    const frag=document.createDocumentFragment();
    [...t.data].forEach(c=>{
      if(news.includes(c)){const sp=document.createElement('span');sp.style.color='#ffd23f';sp.textContent=c;frag.appendChild(sp)}
      else frag.appendChild(document.createTextNode(c));
    });
    t.parentNode.replaceChild(frag,t);
  });
  const items=news.map(c=>{const [k,on,mean,kun]=KX[c];const kn=on?kana(on):'';
    return `<p style="margin:4px 0"><b style="color:#ffd23f;font-size:1.3rem">${k}</b> · ${on||'-'}${kn?' · '+kn:''}${kun?' · kun: '+kun:''} <small>— ${mean}</small></p>`}).join('');
  fc.insertAdjacentHTML('afterend',`<div class="card" style="border-color:#ffd23f"><b>Info kanji baru</b> <small>· bukan bagian soal, hanya muncul sekali</small>${items}</div>`);
  S.seen=[...seen,...news];save();
}
