$.innerHTML=`<button class="bk" onclick="${Q.bk};">← Keluar</button><div class="top"><b>${Q.title}</b><span class="mu">${Math.min(Q.k+1,n)} / ${n}</span></div><div class="bar"><i style="width:${Q.k/n*100}%"></i></div><p class="mu">${q.p}</p><div class="fc" ${q.say?`onclick="say('${q.say}')"`:''} style="font-size:${q.big.length>8?'1.9rem':q.big.length>4?'2.6rem':q.big.length>1?'3.4rem':'5rem'}"><div class="fi">${S.furi&&q.rb?(q.big.length>6?q.big+'<br><small style="font-size:1rem">'+(S.furi==2?kana(q.rb):q.rb)+'</small>':'<ruby>'+q.big+'<rt>'+(S.furi==2?kana(q.rb):q.rb)+'</rt></ruby>'):q.big}</div></div>`+(q.typ?`<input id="ti" class="ti" autocomplete="off" autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="Ketik romaji" onkeydown="if(event.key=='Enter')tsub()"><div id="fb"></div><button class="main" id="sb" onclick="tsub()"><span>Periksa</span></button>`:`<div class="opg">${q.o.map((o,i)=>`<button class="op" onclick="fin(${i})">${o}</button>`).join('')}</div><div id="fb"></div>`);
