function fin(i){const q=Q.qs[Q.k];if(Q.lock)return;Q.lock=1;const ok=q.o[i]===q.a;document.querySelectorAll('.op').forEach((b,j)=>{b.disabled=true;if(q.o[j]===q.a)b.classList.add('ok');else if(j==i)b.classList.add('no')});mark(ok);const c=Q;setTimeout(()=>{if(Q===c){Q.lock=0;Q.k++;ask()}},ok?700:1300)}
