if(locked){$.insertAdjacentHTML('beforeend',`<button class="main alt lk" onclick="rowStudy(${i},'${lockMsg}')"><span>🔒 Tahap 5 · Penguatan<small>terbuka setelah tema ini dilalui</small></span><span></span></button>`);return}
