/* Kenalan: satu kanji per layar, lalu dicek */
let KN;
function kenal(i,re){tab('belajar');const n=ROW[i].L.length,kp=(S.kp||{})[i]||0;KN={i,k:(!re&&!kenalDone(i)&&kp>0&&kp<n)?kp:0,m:'l',q:0};knShow()}
function knNext(){S.kp=S.kp||{};S.kp[KN.i]=KN.k+1;save();KN.k++;KN.m='l';KN.q=0;knShow()}
function knShow(){const{i,k,m,q}=KN,r=ROW[i],n=r.L.length;DB='rowStudy('+i+')';
if(k>=n){S.kn=S.kn||{};if(!S.kn[i]){S.kn[i]=1;S.xp+=3}save();
return $.innerHTML=`<button class="bk" onclick="rowStudy(${i})">← Kembali ke tema</button><h2>Kenalan selesai 🎉</h2><p class="mu">Kamu sudah mengenal ${n} kanji di Tema ${r.c}. Langkah berikutnya: Tahap 1 (arti).</p>${grid(r.L,5)}<button class="main" onclick="rowQuiz(${i},1)"><span>Mulai Tahap 1 · Arti</span><span>→</span></button>`}
const x=r.L[k],c=x[0],hd=`<button class="bk" onclick="rowStudy(${i})">← Keluar</button><div class="top"><b>Kenalan · Tema ${r.c}</b><span class="mu">${k+1} / ${n}</span></div><div class="bar"><i style="width:${(k+(m=='c'?.5:0))/n*100}%"></i></div>`;
if(m=='l'){const ws=W.filter(w=>[...w[0]].includes(c)).slice(0,4);say(c);
$.innerHTML=hd+`<p class="mu">Langkah 1 dari 2: pelajari kanji ini pelan-pelan.</p><button class="main" onclick="KN.m='c';KN.q=0;knShow()"><span>Saya siap dicek<small>2 pertanyaan: arti, lalu bacaan</small></span><span>→</span></button><div class="fc big" onclick="say('${c}')">${c}</div><div class="card"><b style="font-size:1.4rem">${x[2]}</b><p>Bacaan umum: <b>${x[1]}</b>${x[3]?'<br>Bacaan lain: '+x[3]:''}<br>Jumlah goresan: <b>${ST[c]||'-'}</b></p><p class="mu"><small>Bacaan umum adalah yang ditanyakan di kuis. Bacaan lain muncul di kata tertentu.</small></p>${MN[c]?'<p><b>Cara mengingat</b><br>'+MN[c]+'</p>':''}</div>${ws.length?'<h3>Contoh kata</h3>'+ws.map(w=>`<button class="wd" onclick="say('${w[0]}')"><b>${w[0]}</b><span>${S.furi==2?kana(w[1]):w[1]}</span><small>${w[2]}</small></button>`).join(''):''}${readingBox(c)}${sentBox(c)}<h3>Coba tulis</h3>${strokeBox(c)}<p class="mu">Tulis dengan jari mengikuti urutan di atas. Garis bantu bisa dinyalakan atau dimatikan.</p><div class="fc pw"><span id="gd">${c}</span><canvas id="pd"></canvas></div><div class="acts"><button class="ghost" onclick="pad()">Hapus</button><button class="ghost" onclick="gd.hidden=!gd.hidden">Garis bantu</button><button class="go" onclick="cekTulis()">Periksa tulisan</button></div><div id="skr"></div>`;pad()}
else{const a=q==0?x[2]:x[1],o=uniq(a,()=>R(ALL)[q==0?2:1]);KN.o=o;KN.a=a;
$.innerHTML=hd+`<p class="mu">Langkah 2 dari 2 · cek ${q+1}/2: ${q==0?'Apa arti kanji ini?':'Apa bacaan umum kanji ini?'}</p><div class="fc big" onclick="say('${c}')">${c}</div><div class="opg">${o.map((t,j)=>`<button class="op" onclick="knAns(${j})">${t}</button>`).join('')}</div><div id="fb"></div><div id="ac"><button class="ghost" onclick="KN.m='l';knShow()">← Lihat materi lagi</button></div>`}}
function knAns(j){const x=ROW[KN.i].L[KN.k],ok=KN.o[j]===KN.a,last=KN.k==ROW[KN.i].L.length-1;
document.querySelectorAll('.op').forEach((b,t)=>{b.disabled=true;if(KN.o[t]===KN.a)b.classList.add('ok');else if(t==j)b.classList.add('no')});snd(ok);rec(x[0],ok);
document.getElementById('fb').innerHTML=`<div class="fb ${ok?'ok':'no'}"><b>${ok?'Benar!':'Jawaban: '+KN.a}</b></div>`;
document.getElementById('ac').innerHTML=!ok?`<button class="main" onclick="KN.m='l';knShow()"><span>Pelajari lagi<small>Baca materinya sekali lagi, lalu dicek ulang</small></span><span>→</span></button>`:KN.q==0?`<button class="main" onclick="KN.q=1;knShow()"><span>Lanjut: cek bacaan</span><span>→</span></button>`:`<button class="main" onclick="knNext()"><span>${last?'Selesai kenalan':'Kanji berikutnya'}</span><span>→</span></button>`}
/* Flashcard */
let FC;function flash(){FC={d:SH(LP()).slice(0,20),k:0,b:0,ok:0,no:[]};card()}
function card(){tab('belajar');const c=FC.d[FC.k];if(!c){return $.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Selesai!</h2><div class="score"><b>${FC.ok}/${FC.d.length}</b>kartu hafal</div><p>${FC.no.length?'Perlu diulang: <b style="font-size:1.4rem">'+FC.no.join(' ')+'</b>':'Semua hafal!'}</p><div class="acts"><button class="ghost" onclick="flash()">Ulangi</button></div>`}
$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><div class="top"><b>Kartu Hafalan</b><span class="mu">${FC.k+1}/${FC.d.length}</span></div><div class="fc" onclick="${FC.b?`say('${c[0]}')`:'FC.b=1;card()'}" style="flex-direction:column"><span>${c[0]}</span>${FC.b?`<small style="font-size:1.4rem">${c[1]}<br>${c[2]}</small>`:'<small style="font-size:1rem">Ketuk untuk melihat bacaan</small>'}</div>`+(FC.b?`<div class="acts"><button class="ghost" onclick="fcMark(0)">Belum hafal</button><button class="go" onclick="fcMark(1)">Hafal</button></div>`:'')}
