/* Sesi harian (pengulangan berjeda) */
const INT=[0,1,2,4,8,16],CUR=ALL.map(x=>x[0]);
function plan(){const E=S.srs,td=dk(),due=Object.keys(E).filter(c=>E[c].d<=td).sort((a,b)=>E[a].d<E[b].d?-1:1).slice(0,25),tn=Object.values(E).filter(e=>e.l==td).length;
return{due,nw:due.length>20?[]:avail().filter(c=>!E[c]).slice(0,Math.max(0,S.baru-tn))}}
function sesi(){tab('belajar');const p=plan(),cnt=[0,0,0,0];CUR.forEach(c=>{const e=S.srs[c];cnt[!e?0:e.b>=4?3:e.b==3?2:1]++});const col=['var(--bd)','var(--ac)','#f59e0b','var(--ok)'],nm=['Baru','Belajar','Hampir hafal','Hafal'],tot=p.nw.length+p.due.length;
$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Sesi Harian</h2><p class="mu">Kanji baru pada sesi ini hanya berasal dari tema yang sudah dikenalkan di Kurikulum Kanji, sehingga materi tetap berurutan. Setiap kanji dikuis, lalu diulang dengan jeda yang makin panjang (1, 2, 4, 8, dan 16 hari).</p>${avail().length?'':'<div class="fb no">Belum ada kanji yang terbuka. Mulai dari Kurikulum Kanji, Tema 1, Kenalan.</div><button class="main" onclick="jalur()"><span>Buka Kurikulum Kanji</span><span>→</span></button>'}<div style="display:flex;height:16px;border-radius:99px;overflow:hidden;background:var(--bd)">${cnt.map((v,i)=>`<i style="width:${v/CUR.length*100}%;background:${col[i]}"></i>`).join('')}</div><p><small>${cnt.map((v,i)=>nm[i]+' '+v).join(' · ')}</small></p><div class="hist"><b>${p.nw.length}</b> kanji baru · <b>${p.due.length}</b> diulang</div><div class="chips"><small style="align-self:center">Kanji baru/hari:</small>${[3,5,10].map(n=>`<button class="${S.baru==n?'on':''}" onclick="S.baru=${n};save();sesi()">${n}</button>`).join('')}</div><button class="main" ${tot?'':'disabled'} onclick="sesiMulai()"><span>${tot?'Mulai sesi':'Selesai untuk hari ini ✓'}</span><span>→</span></button>`}
function sesiMulai(){const p=plan();SS={nw:p.nw,due:p.due,ik:0};SS.nw.length?sesiIntro():sesiQuiz()}
function sesiIntro(){const c=SS.nw[SS.ik];if(!c)return sesiQuiz();say(c);
$.innerHTML=`<button class="bk" onclick="sesi()">← Kembali</button><div class="top"><b>Kenalan kanji baru</b><span class="mu">${SS.ik+1}/${SS.nw.length}</span></div><div class="fc" onclick="say('${c}')" style="flex-direction:column"><span>${c}</span><small style="font-size:1.4rem">${KR[c]}<br>${KX[c][2]}</small></div>${MN[c]?'<p class="mu">'+MN[c]+'</p>':''}<button class="main" onclick="SS.ik++;sesiIntro()"><span>Lanjut</span><span>→</span></button>`}
function sesiQuiz(){const mk=(c,nw)=>{const e=S.srs[c],b=nw?0:e.b,P=isD(c)?HD:HB.length?ALL:ALL,x=KX[c];return b>=4&&Math.random()<.5?qr2k(x,ALL):b>=2?qty(x):qk2r(x,ALL)};
const qs=[...SS.nw.map(c=>mk(c,1)),...SH(SS.due.map(c=>mk(c,0)))];if(!qs.length)return sesi();Q={title:'Sesi Harian',srs:1,pts:0,qs,k:0,r:[],nw:new Set(SS.nw),f:[],bk:'sesi()'};ask()}
function srsFin(q,ok){if(q.rt){if(!ok)Q.qs.push({...q,o:SH(q.o)});return}const c=q.ch,nw=Q.nw.has(c),e=S.srs[c]||{b:0,l:dk()},b0=e.b;const sec=(Date.now()-(Q.t0||Date.now()))/1000;e.b=nw?1:ok?(sec>15?Math.max(1,e.b):Math.min(5,e.b+(sec<4&&e.b>=3?2:1))):Math.max(1,e.b-2);e.d=addD(INT[e.b]);S.srs[c]=e;Q.f.push({c,ok,nw,b0,b:e.b});if(!ok)Q.qs.push({...q,rt:1,o:SH(q.o)});save()}
function srsDone(){const F=Q.f,ok=F.filter(x=>x.ok).length,bad=F.filter(x=>!x.ok).map(x=>x.c);S.xp+=Math.round(ok/2);save();
$.innerHTML=`<button class="bk" onclick="sesi()">← Kembali</button><h2>Sesi selesai! 🎉</h2><div class="score"><b>${F.length?Math.round(ok/F.length*100):0}%</b>benar di percobaan pertama</div><p><b>${F.filter(x=>x.nw).length}</b> kanji baru · <b>${F.filter(x=>!x.nw).length}</b> diulang</p>${bad.length?`<p>Perlu diperhatikan: <b style="font-size:1.4rem">${[...new Set(bad)].join(' ')}</b></p>`:''}<div class="acts"><button class="ghost" onclick="home()">Beranda</button></div>`}
