function kilat(){tab('belajar');$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Kuis Cepat</h2><p class="mu">Kanji diambil dari tema yang sudah kamu kenalan. Jawab secepat mungkin dalam 60 detik. Beruntun menambah combo. Salah mengurangi skor dan 2 detik waktu.</p><div class="hist">Rekor: <b>${S.kilat}</b></div><button class="main" onclick="kStart()"><span>Mulai</span><span>→</span></button>`}
function kStart(){KG={sk:0,cb:0,ok:0,no:0,t:60,mx:0,lock:0};kNext();tm=setInterval(()=>{KG.t--;const e=document.getElementById('kt');if(e)e.textContent=KG.t;if(KG.t<=0)kEnd()},1000)}
function kNext(){const P=LP(),x=R(P),q=Math.random()<.5?qk2r(x,P):qr2k(x,P);KG.q=q;KG.lock=0;
$.innerHTML=`<div class="top"><b>⏱ <span id="kt">${KG.t}</span></b><b>Skor ${KG.sk}</b><b>🔥 x${KG.cb}</b></div><p class="mu">${q.p}</p><div class="fc" style="font-size:4rem">${q.big}</div><div class="opg">${q.o.map((o,i)=>`<button class="op" onclick="kAns(this,${i})">${o}</button>`).join('')}</div>`}
function kAns(b,i){if(KG.lock||KG.t<=0)return;KG.lock=1;const q=KG.q,ok=q.o[i]===q.a;snd(ok);rec(q.ch,ok);
if(ok){KG.ok++;KG.cb++;KG.mx=Math.max(KG.mx,KG.cb);KG.sk+=10+Math.min(KG.cb,10)*2}else{KG.no++;KG.cb=0;KG.sk=Math.max(0,KG.sk-5);KG.t=Math.max(0,KG.t-2)}
document.querySelectorAll('.op').forEach(x=>{x.disabled=true;if(x.textContent===q.a)x.classList.add('ok')});if(!ok)b.classList.add('no');const g=KG;setTimeout(()=>{if(g.t>0&&KG===g)kNext()},ok?250:700)}
function kEnd(){clearInterval(tm);const nb=KG.sk>S.kilat;if(nb)S.kilat=KG.sk;S.xp+=Math.round(KG.sk/10);save();
$.innerHTML=`<h2 style="text-align:center;margin-top:30px">Waktu habis! ⏱</h2><div class="score"><b>${KG.sk}</b>${nb?'Rekor baru! 🎉':'skor (terbaik '+S.kilat+')'}</div><p style="text-align:center">${KG.ok} benar · ${KG.no} salah · combo terbaik x${KG.mx}</p><div class="acts"><button class="ghost" onclick="kStart()">Main lagi</button><button class="ghost" onclick="belajar()">Kembali</button></div>`}
