let TF='';const lvk=c=>{const l=LV(c);return l.includes('N5')?'N5':l.includes('N4')?'N4':'N3'},rowsF=()=>ROW.map(r=>({c:r.c,L:r.L.filter(x=>!TF||lvk(x[0])==TF)})).filter(r=>r.L.length);
const N5S=new Set([...'日一国人年大十二本中長出三時行見月後前生五間上東四今金九入学高円子外八六下来気小七山話女北午百書先名川千水半男西電校語土木聞食車何南万毎白天母火右読友左休父雨分週目耳口手足安新古多少立言買会店']),EXS=new Set([...'零億数星昨晩君鼻身石雪雲光島湖村市県都区横虫黄緑薬痛健洗払忘覚渡続決絵泊番点第号交愛悲笑泣怒想情当全予定約束練合原由説返付例祖孫米菜冷暖若深商末期達季主局式池側角熱首荷届皮']);
