const LV=c=>N5S.has(c)?'JLPT N5':N4S.has(c)?'JLPT N4':'N3+ (di luar daftar N4)';
function ringkas(){const hf=n=>{let t=0,h=0;ALL.forEach(x=>{if(lvk(x[0])==n){t++;if(lv(x[0])==3)h++}});return[h,t]};
const lv2=[['N5','N5'],['N4','N4'],['N3','Tambahan']].filter(([k])=>hf(k)[1]>0).map(([k,n])=>{const[h,t]=hf(k);return `<div class="row"><span><b>${n}</b> <small>${h}/${t} hafal</small></span><b>${Math.round(h/t*100)}%</b></div><div class="bar"><i style="width:${h/t*100}%"></i></div>`}).join('');
const dn=ROW.filter((_,i)=>S.baris[i]>=80).length,left=ROW.length-dn,days=Object.keys(S.daily).length,est=dn&&days?Math.ceil(left*days/dn):0;
const wk=[...Array(7)].reduce((a,_,n)=>{const d=new Date();d.setDate(d.getDate()-n);return a+(S.daily[dk(d)]||0)},0);
const nx=Object.values(S.srs).filter(e=>e.d<=addD(7)).length;
const th=ROW.map((r,i)=>{const h=r.L.filter(x=>lv(x[0])==3).length;return `<div class="row"><small>${i+1}. ${r.c}</small><small>${h}/${r.L.length} hafal${S.baris[i]>=80?' ✓':''}</small></div>`}).join('');
return `<h3>Penguasaan per level</h3><div class="hist">${lv2}</div><div class="hist"><div class="row"><span>Tema selesai</span><b>${dn}/${ROW.length}</b></div><div class="row"><span>Estimasi selesai</span><b>${est?'± '+est+' hari belajar lagi':'mulai dulu'}</b></div><div class="row"><span>Soal 7 hari terakhir</span><b>${wk}</b></div><div class="row"><span>Diulang 7 hari ke depan</span><b>${nx} kanji</b></div></div><details class="card"><summary><b>Per tema</b></summary>${th}</details>`}
