function progres(){tab('progres');const t=S.daily[dk()]||0,g=S.target,pct=Math.min(100,t/g*100),h=S.hist.slice(0,10);
const hard=Object.entries(S.stat).filter(([c,e])=>e.w>0&&e.c+e.w>=3).map(([c,e])=>[c,Math.round(e.c/(e.c+e.w)*100),e.c+e.w]).sort((a,b)=>a[1]-b[1]).slice(0,6);
const mast=CUR.filter(c=>lv(c)==3).length;
$.innerHTML=`<h2>Progres Belajar</h2><div class="hist"><div class="row"><b style="font-size:1.6rem">${streak()}</b><span class="mu">hari berturut-turut · ${S.xp} XP</span></div><div class="top" style="margin-top:8px"><span class="mu">Target harian</span><b>${t}/${g}</b></div><div class="bar"><i style="width:${pct}%"></i></div><div class="chips">${[10,20,40].map(n=>`<button class="${g==n?'on':''}" onclick="S.target=${n};save();progres()">${n} soal/hari</button>`).join('')}</div><small class="mu">Target mingguan (7 hari):</small><div class="chips">${[70,140,210].map(n=>`<button class="${(S.wgoal||140)==n?'on':''}" onclick="S.wgoal=${n};save();progres()">${n} soal</button>`).join('')}</div></div>
${ringkas()}<h3>Peta penguasaan kanji <small>${mast}/${CUR.length} hafal</small></h3><style>.kb{display:flex;flex-direction:column;align-items:center;gap:3px;padding:7px 3px 5px;border:1px solid var(--bd);border-radius:12px;background:var(--cd);color:var(--tx);min-width:0}.kb b{font:600 1.4rem var(--serif)}.kb .bt{display:block;width:100%;height:6px;border-radius:4px;background:var(--bd);overflow:hidden}.kb .bt i{display:block;height:100%;border-radius:4px}.kb small{font-size:.7rem;color:var(--mu)}.kb.f{background:#fff;border-color:#fff}.kb.f b{color:#172036}.kb.f small{color:#172036;font-weight:700}.kb.f .bt{background:#d5dbea}.kb .bt i.w{box-shadow:inset 0 0 0 1px #aab3cc}.pl{display:flex;flex-wrap:wrap;gap:6px 12px;margin:4px 0 10px}.pl span{display:inline-flex;align-items:center;gap:5px;font-size:.78rem;color:var(--mu)}.pl em{width:12px;height:12px;border-radius:4px;display:inline-block}</style><div class="pl"><span><em style="background:#e5484d"></em>&lt;30% belum hafal</span><span><em style="background:#f5b84a"></em>30-79% lumayan</span><span><em style="background:#3fb871"></em>80-99% hampir hafal</span><span><em style="background:#fff;border:1px solid #aab3cc"></em>100% hafal</span></div><p><small>Benar +10%, salah -10%. Untuk mencapai 100% harus 10x benar berturut-turut.</small></p>${TOPK.map(([n,cs])=>{const L=[...cs].filter(c=>KX[c]).map(c=>KX[c]);return `<h4 style="margin:14px 0 4px">${n} <small class="mu">${L.length} kanji</small></h4><div class="g" style="grid-template-columns:repeat(5,1fr);gap:6px">${L.map(x=>{const p=pt(x[0]),col=p>=100?'#fff':p>=80?'#3fb871':p>=30?'#f5b84a':'#e5484d';return `<button class="kb${p>=100?' f':''}" onclick="DB='progres()';detail('${x[0]}')"><b>${x[0]}</b><span class="bt"><i class="${p>=100?'w':''}" style="width:${p}%;background:${col}"></i></span><small>${p>=100?'✓ ':''}${p}%</small></button>`}).join('')}</div>`}).join('')}
<h3>Kanji tersulit</h3>${hard.length?hard.map(([c,p,n])=>`<div class="row"><span style="font-size:1.6rem">${c} <small>${KR[c]}</small></span><small>akurasi ${p}% dari ${n}</small></div>`).join(''):'<p class="mu">Belum cukup data.</p>'}
<h3>Riwayat nilai</h3>${h.map(x=>`<div class="row"><span>${x.t}</span><small>${x.ok}/${x.n} · ${new Date(x.d).toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</small></div>`).join('')||'<p class="mu">Belum ada.</p>'}
<h3>Tampilan</h3><div class="hist"><div class="row"><span>Tema</span><span>${[['auto','Otomatis'],['light','Terang'],['dark','Gelap']].map(x=>`<button class="ghost" style="${(S.theme||'auto')==x[0]?'font-weight:800;text-decoration:underline':''}" onclick="setLook('theme','${x[0]}')">${x[1]}</button>`).join(' ')}</span></div><div class="row"><span>Ukuran huruf</span><span>${[[90,'Kecil'],[100,'Normal'],[115,'Besar'],[130,'Sangat besar']].map(x=>`<button class="ghost" style="${(S.fz||100)==x[0]?'font-weight:800;text-decoration:underline':''}" onclick="setLook('fz',${x[0]})">${x[1]}</button>`).join(' ')}</span></div></div><h3>Pengaturan suara</h3><div class="hist"><div class="row"><span>Efek suara benar dan salah</span><button class="ghost" onclick="S.snd=S.snd?0:1;save();progres()">${S.snd?'Nyala':'Mati'}</button></div><div class="row"><span>Lafal bahasa Jepang</span><button class="ghost" onclick="S.tts=S.tts===0?1:0;save();progres()">${S.tts===0?'Mati':'Nyala'}</button></div><div class="row"><span>Kecepatan bicara</span><div class="chips" style="margin:0">${[[.6,'Pelan'],[.85,'Normal'],[1,'Cepat']].map(x=>`<button class="${(S.rate||.85)==x[0]?'on':''}" onclick="S.rate=${x[0]};save();progres()">${x[1]}</button>`).join('')}</div></div><div class="acts"><button class="ghost" onclick="tesSuara()">Tes suara Jepang</button></div><p id="sm" class="mu"></p></div><h3>Pengaturan dan cadangan data</h3><div class="acts"><button class="ghost" onclick="S.furi=((S.furi||0)+1)%3;save();progres()">Furigana: ${['mati','romaji','hiragana'][S.furi|0]}</button><button class="ghost" onclick="bk()">Cadangkan / pulihkan data</button><button class="ghost" onclick="tesSuara()">Tes suara</button><button class="ghost" onclick="S.ob=0;save();home()">Lihat panduan awal</button></div><p class="mu" id="sm"></p>`}
function bk(){const code=btoa(unescape(encodeURIComponent(JSON.stringify(S))));
$.innerHTML=`<button class="bk" onclick="progres()">← Kembali</button><h2>Cadangan dan Pemindahan Data</h2><p class="mu">Progresmu tersimpan di browser perangkat ini saja. Untuk pindah HP, ganti browser, atau berjaga-jaga, simpan backup lalu pulihkan di perangkat lain.</p><div class="acts"><button class="go" onclick="bkCopy()">Salin kode</button><button class="ghost" onclick="bkFile()">Unduh file</button></div><textarea id="bt">${code}</textarea><div class="acts"><button class="go" onclick="bkImp()">Pulihkan dari kode di atas</button></div><p class="mu">Atau pilih file backup:</p><input type="file" id="bf" accept=".txt,text/plain" onchange="bkLoad(this)"><div class="acts"><button class="ghost" onclick="if(confirm('Hapus semua progres?')){S={stat:{},salah:{},srs:{},daily:{},hist:[],baris:{},xp:0,target:20,baru:5,kilat:0,snd:1,furi:2};save();home()}">Reset semua</button></div><p id="bm" class="mu"></p>`}
function bkCopy(){const t=document.getElementById('bt'),m=document.getElementById('bm');t.select();let ok=0;try{ok=document.execCommand('copy')}catch(e){}try{navigator.clipboard&&navigator.clipboard.writeText(t.value);ok=1}catch(e){}S.lastbk=Date.now();save();m.textContent=ok?'Kode disalin. Simpan di tempat aman, misalnya catatan atau chat ke diri sendiri.':'Tekan lama kode di atas, lalu salin.'}
function bkFile(){const m=document.getElementById('bm');(async()=>{try{const d=await claude.use('downloads');if(!d){m.textContent='Unduh tidak tersedia di sini. Pakai tombol Salin kode.';return}await d.save({filename:'japankanji-backup-'+dk()+'.txt',data:document.getElementById('bt').value});S.lastbk=Date.now();save();m.textContent='File backup diunduh.'}catch(e){m.textContent='Gagal mengunduh. Pakai tombol Salin kode.'}})()}
function bkLoad(i){const f=i.files&&i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{document.getElementById('bt').value=String(r.result).trim();bkImp()};r.readAsText(f)}
function bkImp(){try{const p=JSON.parse(decodeURIComponent(escape(atob(document.getElementById('bt').value.trim()))));S=Object.assign(S,p);if(!p.thv4){['thv2','thv3','thv4'].forEach(k=>{if(!(k in p))delete S[k]});save();location.reload();return}save();home()}catch(e){document.getElementById('bm').textContent='Kode tidak valid.'}}
function bkBanner(){const act=Object.keys(S.daily).length>=3&&Date.now()-(S.lastbk||0)>7*864e5;return act?`<div class="fb no"><b>Simpan progresmu</b><br><small>Progres hanya ada di browser ini. Buat backup supaya aman kalau data browser terhapus atau kamu pindah HP.</small><div class="acts"><button class="ghost" onclick="bk()">Backup sekarang</button></div></div>`:''}
