let SKP=[],SPT=[];function pad(){SKP=[];const cv=document.getElementById('pd');if(!cv)return;const r=cv.getBoundingClientRect(),g=cv.getContext('2d');cv.width=r.width*2;cv.height=r.height*2;g.lineWidth=16;g.lineCap=g.lineJoin='round';g.strokeStyle=getComputedStyle(cv).color;let d=0,p,n=0;const ro=document.getElementById('skr');if(ro)ro.innerHTML='';const gk=(document.getElementById('gd')||{}).textContent,ht=()=>strokeHint(gk,n);ht();const xy=e=>{const b=cv.getBoundingClientRect();return[(e.clientX-b.left)*2,(e.clientY-b.top)*2]};cv.onpointerdown=e=>{d=1;p=xy(e);SPT=[p];cv.setPointerCapture(e.pointerId);g.beginPath();g.moveTo(p[0],p[1]);g.lineTo(p[0]+.1,p[1]);g.stroke()};cv.onpointermove=e=>{if(!d)return;const q=xy(e);g.beginPath();g.moveTo(p[0],p[1]);g.lineTo(q[0],q[1]);g.stroke();p=q;SPT.push(q)};cv.onpointerup=cv.onpointercancel=()=>{if(d){n++;SKP.push(SPT);ht()}d=0}}
