/* Ulangan kata dan kalimat (SRS) */
const ITEM=new Map([...W,...SENT].map(x=>[x[0],x])),SSET=new Set(SENT.map(t=>t[0]));
function wplan(){S.wsrs=S.wsrs||{};const E=S.wsrs,td=dk(),ks=new Set(avail()),ok=[...ITEM.keys()].filter(t=>{const a=[...t].filter(c=>KJRE.test(c));return a.length>0&&a.every(c=>ks.has(c))}),due=Object.keys(E).filter(t=>E[t].d<=td&&ITEM.has(t)).slice(0,15),tn=Object.values(E).filter(e=>e.l==td).length;return{due,nw:ok.filter(t=>!E[t]).slice(0,Math.max(0,S.baru-tn))}}
const wLabel=()=>{const p=wplan();return p.nw.length+p.due.length?p.nw.length+' kanji baru · '+p.due.length+' ulangan':'Selesai untuk hari ini ✓'};
function wq(t){const[k,r,m]=ITEM.get(t),s=SSET.has(k),q=s||Math.random()<.5?{p:s?'Apa arti kalimat ini?':'Apa arti kata ini?',big:k,a:m,rb:r,note:'Bacaan: '+r,say:k,o:uniq(m,()=>R(s?SENT:W)[2])}:{p:'Bagaimana membaca kata ini?',big:k,a:r,note:'Arti: '+m,say:k,o:uniq(r,()=>R(W)[1])};q.w=t;return q}
function wRemedial(){const ts=Object.entries(S.wsalah||{}).sort((a,b)=>b[1]-a[1]).map(x=>x[0]).filter(t=>ITEM.has(t)).slice(0,10);if(!ts.length)return belajar();Q={title:'Kosakata yang Sering Salah',pts:0,wsrs:1,qs:SH(ts).map(wq),k:0,r:[],f:[],bk:'belajar()',again:wRemedial};ask()}
function wSesi(){const p=wplan(),ts=[...p.nw,...p.due];if(!ts.length)return belajar();Q={title:'Ulangan Kosakata',pts:0,wsrs:1,qs:SH(ts).map(wq),k:0,r:[],f:[],bk:'belajar()',again:wSesi};ask()}
function wFin(q,ok){if(!q.w)return;S.wsalah=S.wsalah||{};if(ok){if(S.wsalah[q.w]&&--S.wsalah[q.w]<=0)delete S.wsalah[q.w]}else S.wsalah[q.w]=(S.wsalah[q.w]||0)+1;S.wsrs=S.wsrs||{};const e=S.wsrs[q.w]||{b:0,l:dk()};e.b=ok?Math.min(5,e.b+1):Math.max(1,e.b-2);e.d=addD(INT[e.b]);S.wsrs[q.w]=e;Q.f.push({t:q.w,ok});save()}
function wDone(){const F=Q.f,ok=F.filter(x=>x.ok).length,bad=F.filter(x=>!x.ok).map(x=>x.t);S.xp+=Math.round(ok/2);save();
$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Ulangan selesai 🎉</h2><div class="score"><b>${F.length?Math.round(ok/F.length*100):0}%</b>benar · ${ok} dari ${F.length}</div>${bad.length?'<p>Perlu diulang:</p>'+bad.map(t=>`<div class="row"><b style="font-family:var(--serif)">${t}</b><small>${ITEM.get(t)[2]}</small></div>`).join(''):''}<div class="acts"><button class="ghost" onclick="home()">Beranda</button></div>`}
/* Latihan Panduan: radikal, okurigana, partikel */
const RG=[['氵 (air)','泳'],['亻 (orang)','休何使作住'],['言 (ucapan)','話語読言'],['辶 (jalan)','週道近遠送'],['門 (gerbang)','開閉間聞問'],['宀 (atap)','家室安寒'],['食 (makan)','飯飲']],PT='はをにでとの';
const OK4=[['Apa arti kata ini?','開く','terbuka sendiri',['terbuka sendiri','membuka sesuatu','menutup sesuatu','tertutup sendiri'],'開ける akeru = membuka sesuatu. 開く aku = terbuka sendiri.'],['Ekor い pada kata ini menandakan…','大きい','kata sifat',['kata sifat','kata kerja','partikel','kata benda'],'Kata sifat berakhiran い: 大きい, 新しい, 高い.'],['Saat 食べる jadi 食べた, bagian mana yang berubah?','食べる','ekor hiragana',['ekor hiragana','kanji 食','keduanya','tidak ada'],'Kanji tetap, hanya ekor hiragana yang berubah.'],['Bagaimana membaca kata ini?','開ける','akeru',['akeru','aku','hiraku','akeri'],'開ける akeru = membuka sesuatu.']];
const pix=c=>c.map((x,i)=>PT.includes(x)&&!(x=='で'&&c[i+1]=='す')?i:-1).filter(i=>i>=0);
function latPanduan(){
const rq=Array.from({length:4},()=>{const g=R(RG),a=R([...g[1]]),pool=RG.filter(x=>x!==g).flatMap(x=>[...x[1]]),o=new Set([a]);while(o.size<4)o.add(R(pool));return{p:'Kanji mana yang memakai radikal ini?',big:g[0],a,note:[...g[1]].join(' ')+' memakai radikal tersebut.',o:SH([...o])}});
const ps=SENT.filter(t=>pix([...t[0]]).length),pq=Array.from({length:4},()=>{const[k,r,m]=R(ps),c=[...k],a=c[R(pix(c))];c[c.indexOf(a)]='＿';const o=new Set([a]);while(o.size<4)o.add(R([...PT]));return{p:'Partikel apa yang hilang? Arti: '+m,big:c.join(''),a,note:k+' = '+r,o:SH([...o])}});
const oq=OK4.map(([p,big,a,o,n])=>({p,big,a,note:n,o:SH(o)}));
Q={title:'Radikal, Okurigana, dan Partikel',pts:5,qs:SH([...rq,...pq,...oq]),k:0,r:[],bk:'belajar()',again:latPanduan};ask()}

