function plcDone(){let n=0;while(n<ROW.length&&Q.qs.every((q,j)=>q.th!=n||Q.r[j]))n++;S.kn=S.kn||{};for(let i=0;i<n;i++){S.kn[i]=1;S.baris[i]=Math.max(S.baris[i]||0,80)}S.xp+=n*3;save();
$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Hasil penempatan</h2><div class="score"><b>${n}/${ROW.length}</b>tema dilewati</div><p class="mu">${n?'Tema 1 sampai '+n+' ditandai lulus. Kamu mulai dari Tema '+(n<ROW.length?ROW[n].c:'terakhir')+'.':'Belum ada tema yang dilewati. Mulailah dari Tema 1.'} Tema dilewati hanya jika dua soalnya benar semua dan berurutan dari awal.</p><div class="acts"><button class="ghost" onclick="jalur()">Buka Kurikulum Kanji</button></div>`}

/* Prioritas belajar: P1 sampai P4 */
function PRI(i){return i<=9?1:i<=13?2:i<=22?3:4}
function priDone(t){return ROW.every((_,i)=>PRI(i)!=t||S.baris[i]>=80)}
function curPri(){for(let t=1;t<=4;t++)if(!priDone(t))return t;return 4}
function ptag(i){const t=PRI(i);return `<span class="ptag ${priDone(t)?'pg':''}">P${t}</span>`}
function prioritas(){tab('belajar');const T=[[1,'Sangat prioritas','Angka, hari, waktu, orang, sekolah, alam, tubuh, dan arah. Ini paling sering muncul di teks dan kalimat pemula, jadi pelajari dulu.'],[2,'Prioritas tinggi','Ukuran dan sifat, kata kerja dasar, dan benda sehari-hari. Mulai setelah P1 lulus semua.'],[3,'Lanjutan','Kanji N4 inti: waktu dan musim, kata kerja, sekolah dan kerja, makanan, keluarga, dan sifat. Bekal utama untuk N4.'],[4,'Pengayaan','Kanji N4 pelengkap, kanji dasar tambahan (emosi, wilayah, rencana, dan lain-lain), dan kosakata yang lebih jarang. Urutannya dari yang paling sering dipakai: N4 pelengkap, N3, hewan, lalu warna langka. Kerjakan setelah P3 lulus.']];
const dn=t=>ROW.filter((_,i)=>PRI(i)==t&&S.baris[i]>=80).length,tt=t=>ROW.filter((_,i)=>PRI(i)==t).length;
$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Prioritas Belajar</h2><p class="mu">Pelajari dari P1. Label hijau berarti prioritas itu sudah lulus semua, jadi kamu siap lanjut ke prioritas berikutnya.</p>`+T.map(x=>`<div class="card"><div class="row"><span><span class="ptag ${dn(x[0])==tt(x[0])?'pg':''}">P${x[0]}</span> <b>${x[1]}</b></span><small>${dn(x[0])}/${tt(x[0])} tema</small></div><p class="mu">${x[2]}</p></div>`).join('')+`<button class="main" onclick="jalur()"><span>Buka Kurikulum Kanji<small>Prioritas saat ini: P${curPri()}</small></span><span>→</span></button>`}

/* Latihan Menyimak */
function simak(){const sents=SH(SENT).slice(0,6).map(([k,r,m])=>({p:'Dengarkan lalu pilih artinya',big:'🔊',a:m,rb:r,note:k+' = '+r,say:k,o:uniq(m,()=>R(SENT)[2])}));const words=SH(W).slice(0,6).map(([k,r,m])=>({p:'Dengarkan lalu pilih bacaannya',big:'🔊',a:r,note:k+' = '+r+' ('+m+')',say:k,o:uniq(r,()=>R(W)[1])}));
Q={title:'Latihan Menyimak',pts:0,qs:SH([...sents,...words]),k:0,r:[],bk:'belajar()',again:simak};ask()}
function panduan(){tab('belajar');$.innerHTML=`<button class='bk' onclick='belajar()'>← Kembali</button><h2>Cara Membaca Kanji</h2><p class='mu'>Ketuk judul untuk membuka. Baca berurutan dari atas.</p>
<details class='card' open><summary><b>Alur belajar yang disarankan</b></summary><p><i>1.</i> Baca panduan ini sekali.</p><p><i>2.</i> Buka Kurikulum Kanji dan kerjakan berurutan. Tiap tema: Kenalan (satu kanji per layar, lalu dicek arti dan bacaannya), Tahap 1 arti, Tahap 2 bacaan, Tahap 3 kata, Tahap 4 ulasan. Setiap tahap minimal 80% sebelum tahap dan tema berikutnya terbuka.</p><p><i>3.</i> Lanjut ke Sesi Harian agar kanji diulang dengan jeda.</p><p><i>4.</i> Tutup dengan latihan Kalimat dan Bedakan Kanji Mirip.</p></details>
<details class='card'><summary><b>1. Dua jenis bacaan</b></summary><p><i>Kun-yomi</i> adalah bacaan asli Jepang. Muncul pada kanji yang berdiri sendiri atau diikuti hiragana: 山 yama, 食べる taberu, 大きい ookii.</p><p><i>On-yomi</i> adalah bacaan serapan dari Tiongkok. Muncul pada gabungan dua kanji atau lebih: 学校 gakkou, 電話 denwa, 先生 sensei.</p></details>
<details class='card'><summary><b>2. Aturan praktis menebak bacaan</b></summary><p>Satu kanji + hiragana di belakangnya biasanya kun-yomi: 見る miru.</p><p>Dua kanji atau lebih tanpa hiragana biasanya on-yomi: 日本語 nihongo.</p><p>Kanji tunggal tanpa hiragana, seperti 山 川 木, sering kun-yomi.</p><p>Pengecualian yang harus dihafal utuh: 今日 kyou, 一人 hitori, 二人 futari, 大人 otona, 友達 tomodachi.</p></details>
<details class='card'><summary><b>Radikal: kunci memecah kanji</b></summary><p>Kanji rumit biasanya gabungan bagian kecil. Hafalkan bagian yang sering muncul.</p><p><i>氵</i> air: 泳 berenang.</p><p><i>亻</i> orang: 休 beristirahat, 何 apa, 使 menggunakan, 作 membuat, 住 tinggal.</p><p><i>言</i> ucapan: 言 話 語 読.</p><p><i>辶</i> jalan: 週 道 近 遠 送.</p><p><i>門</i> gerbang: 開 閉 間 聞 問.</p><p><i>日</i> matahari: 明 暗 暑 時 昼.</p><p><i>宀</i> atap: 家 室 安 寒.</p><p><i>艹</i> tumbuhan: 花 茶.</p><p><i>食</i> makan: 飯 飲.</p></details>
<details class='card'><summary><b>Okurigana: hiragana di belakang kanji</b></summary><p>Pada kata kerja dan kata sifat, kanji memegang makna, hiragana di belakangnya memegang bentuk kata.</p><p>食べる taberu, 食べます tabemasu, 食べた tabeta: kanji 食 tetap, ekornya berubah.</p><p>大きい ookii, 新しい atarashii, 高い takai: ekor い menandakan kata sifat.</p><p>Okurigana membedakan kata: 開ける akeru (membuka sesuatu) dan 開く aku (terbuka sendiri).</p><p>Itu sebabnya kuis bacaan memakai bacaan umum, lalu kata lengkapnya dilatih di Tahap 3.</p></details>
<details class='card'><summary><b>Partikel dasar di kalimat</b></summary><p><i>は</i> topik: 山は大きいです (gunungnya besar).</p><p><i>を</i> objek: 水を飲みます (minum air).</p><p><i>に</i> tujuan atau waktu: 学校に行きます (pergi ke sekolah), 三時に (jam tiga).</p><p><i>で</i> tempat aksi atau alat: 店で買います (membeli di toko), 電車で (naik kereta).</p><p><i>と</i> bersama: 友達と行きます (pergi dengan teman).</p><p><i>の</i> kepemilikan: 駅の前 (depan stasiun).</p></details>
<details class='card'><summary><b>3. Bunyi yang berubah</b></summary><p>Pengerasan: 学 gaku + 校 kou jadi 学校 gakkou. 十 juu + 分 fun jadi 十分 juppun.</p><p>Penyuaraan: 友 tomo + 達 tachi jadi 友達 tomodachi. 花 hana + 火 hi jadi 花火 hanabi.</p><p>Angka + 分: 一分 ippun, 三分 sanpun, 五分 gofun, 十分 juppun.</p></details>
<details class='card'><summary><b>4. Urutan goresan</b></summary><p><i>1.</i> Atas dulu, baru bawah.</p><p><i>2.</i> Kiri dulu, baru kanan. Pada kanji bergabung seperti 休 dan 明, tulis bagian kiri lebih dulu.</p><p><i>3.</i> Garis mendatar sebelum garis tegak yang memotongnya: 十, 土, 古.</p><p><i>4.</i> Kanji simetris, tulis bagian tengah dulu: 小, 水, 山.</p><p><i>5.</i> Garis miring ke kiri (ノ) sebelum miring ke kanan: 人, 大, 木.</p><p><i>6.</i> Kotak: sisi kiri dan atas-kanan dulu, isi di dalam, lalu tutup bagian bawah paling akhir: 日, 田, 国.</p><p><i>7.</i> Garis tegak yang menembus bagian tengah ditulis terakhir: 中, 手.</p><p><i>8.</i> Bagian 辶 (berjalan) ditulis paling akhir: 道, 近, 送.</p></details><details class='card'><summary><b>5. Membedakan kanji yang mirip</b></summary><p><i>人 入 八:</i> pada 人 kaki kiri lebih panjang, pada 入 kaki kanan lebih panjang, pada 八 kedua kaki terpisah.</p><p><i>日 目 白 田:</i> 日 kotak dengan satu garis tengah, 目 lebih tinggi dengan dua garis, 白 ada titik di atas 日, 田 berisi tanda silang.</p><p><i>大 犬:</i> 犬 punya titik di kanan atas.</p><p><i>左 右:</i> 左 berakhir dengan 工 (alat kerja), 右 berakhir dengan 口 (mulut).</p><p><i>母 毎:</i> 毎 punya "atap" tambahan di atas 母.</p><p><i>木 本:</i> 本 punya garis di bagian akar.</p><p><i>時 持 待:</i> ketiganya memuat 寺. 時 punya 日 (waktu), 持 punya 扌 (tangan, membawa), 待 punya 彳 (jalan, menunggu).</p><p><i>話 語 読:</i> semuanya punya 言 (ucapan) di kiri. Lihat sisi kanan: 話 lidah, 語 "aku", 読 "menjual".</p><p><i>道 近 遠:</i> semuanya punya 辶 (berjalan) di kiri bawah.</p><button class='main' onclick='pick(8)'><span>Latihan: Bedakan Kanji Mirip</span><span>→</span></button></details><details class='card'><summary><b>6. Bacaan umum dan bacaan lain</b></summary><p>Satu kanji bisa punya beberapa bacaan. Di kuis, yang ditanyakan adalah <i>bacaan umum</i>, yaitu bacaan yang paling sering kamu temui.</p><p>Bacaan lain tidak perlu dihafal sekarang. Kamu akan bertemu dengannya di kata-kata, misalnya 日 dibaca <i>hi</i> sendirian, tapi <i>nichi</i> di 日本 (nihon, kata ini memakai ni) dan <i>jitsu</i> di kata lain. Belajar kata adalah cara terbaik menghafal bacaan lain.</p></details><details class='card'><summary><b>7. Partikel dasar di kalimat</b></summary><p><i>は</i> (dibaca wa) menandai topik: 私は学生です, saya seorang pelajar.</p><p><i>が</i> menandai pelaku atau hal yang ada: 犬がいます, ada anjing.</p><p><i>を</i> (dibaca wo) menandai objek: 水を飲みます, saya minum air.</p><p><i>に</i> menandai tujuan, waktu, atau tempat sesuatu berada: 学校に行きます, 三時に会います.</p><p><i>で</i> menandai tempat berbuat sesuatu atau alat: 店で買います, 電車で行きます.</p><p><i>の</i> menunjukkan kepemilikan: 先生の本, buku milik guru.</p><p><i>と</i> berarti dengan atau dan: 友達と行きます, pergi bersama teman.</p><p><i>も</i> berarti juga. <i>から</i> berarti dari, <i>まで</i> berarti sampai.</p><p>Di latihan Kalimat dan Isi Kalimat, perhatikan partikel ini supaya kalimat lebih mudah dibaca.</p></details>`}
/* Cara pakai tiap bacaan: kapan dipakai dan contoh kalimat. Kanji yang belum ada datanya tidak menampilkan bagian ini. */
