const lf=a=>BL?a.filter(x=>x[0]==BL):a.filter(x=>x[0]<=BMAX());
const bsec=(t,b,k)=>`<details class="card"><summary><b>${t}</b></summary>${b}<button class="op" style="width:100%;margin-top:8px" onclick="bq('${k}')">Latih bagian ini</button></details>`;
function bunpou(){if(BL>BMAX())BL=0;tab('belajar');DB='bunpou()';
const J=(t,r)=>`<span onclick="say('${t}')" style="font-size:1.15rem">${t}</span><br><small>${r}</small>`;
const part=lf(PART).map(x=>`<p><b style="font-size:1.4rem">${x[1]}</b> <small>${x[2]}</small><br>${J(x[3],x[4]+' · '+x[5])}</p>`).join('');
const qa=lf(QA).map(x=>`<p><b>${x[1]}</b> <small>${x[2]}</small><br>${J(x[3],'')}<br>→ ${J(x[4],'')}<br><small>${x[5]}</small></p>`).join('');
const dl=lf(DLG).map(x=>`<p><b>${x[1]}</b><br><small>Sopan (desu/masu)</small><br>${x[2].join('<br>')}<br><small>Biasa (bentuk kamus, ke teman/keluarga)</small><br>${x[3].join('<br>')}<br><small>${x[4]}</small></p>`).join('')+`<p><small>Bentuk kamus → sopan:</small><br>${CONJ.map(c=>c[0]+' → '+c[1]+' ('+c[2]+')').join('<br>')}</p>`;
const vc=VOC.map(v=>{const L=v[2].filter(x=>(BL?x[0]==BL:x[0]<=BMAX()));return L.length?`<p><b>${v[1]} ${v[0]}</b><br>${L.map(x=>`<span onclick="say('${x[1]}')">${x[1]}</span> <small>${x[2]} · ${x[3]}</small>`).join('<br>')}</p>`:''}).join('');
const nu=`<p><small>Transitif (を, ada pelaku) vs intransitif (が, terjadi sendiri)</small></p>`+NU.map(x=>`<p><b>${x[3]}</b> <small>${x[4]}</small><br>${x[0]}を${x[1]}。<br>${x[0]}が${x[2]}。</p>`).join('')+CF.map(c=>`<p><b>${c[0]}</b><br><small>${c[1]}</small></p>`).join('');
$.innerHTML=`<button class="bk" onclick="belajar()">← Kembali</button><h2>Tata Bahasa & Dialog</h2><p class="mu">Pilih satu tema dan kerjakan bertahap dalam tiga level, mulai dari Level 1.</p><div class="chips">${[[0,'Semua'],[1,'Level 1'],[2,'Level 2'],[3,'Level 3']].map(x=>`<button class="${BL==x[0]?'on':''}" onclick="BL=${x[0]};bunpou()">${x[1]}</button>`).join('')}</div>`+bsec('1. Partikel (は を に で が の ...)',part,'part')+bsec('2. Tanya-Jawab',qa,'qa')+bsec('3. Percakapan: sopan vs biasa',dl,'dlg')+bsec('4. Kosakata tematik',vc,'voc')+bsec('5. Beda kata & kesalahan umum',nu,'nu')+`<button class="main" onclick="bq('mix')"><span>Latihan Campuran<small>40 soal: partikel, tanya-jawab, dialog, kosakata, beda kata</small></span><span>→</span></button>`;bunpouPost()}
const uq=(a,g)=>uniq(a,g);
const gen={
part:()=>{const x=R(lf(PART).length?lf(PART):PART),s=x[3],i=s.indexOf(x[1]);return{p:'Partikel apa yang cocok? '+x[2],big:s.slice(0,i)+'＿'+s.slice(i+x[1].length),a:x[1],note:s+' = '+x[5],o:uq(x[1],()=>R(PS))}},
qa:()=>{const x=R(lf(QA).length?lf(QA):QA);return Math.random()<.5?{p:'Pilih jawaban yang tepat',big:x[3],a:x[4],note:x[5],say:x[3],o:uq(x[4],()=>R(QA)[4])}:{p:'Pilih pertanyaan yang cocok dengan jawaban ini',big:x[4],a:x[3],note:x[5],say:x[4],o:uq(x[3],()=>R(QA)[3])}},
dlg:()=>{if(Math.random()<.5){const x=R(CONJ);return{p:'Ubah ke bentuk sopan (masu)',big:x[0],a:x[1],note:x[2],say:x[1],o:uq(x[1],()=>R(CONJ)[1])}}const x=R(DLG);return{p:'Ubah ke bentuk biasa untuk bicara dengan teman',big:x[2][0]+' '+x[2][1],a:x[3][1],note:x[4],o:uq(x[3][1],()=>R(DLG)[3][1])}},
voc:()=>{const A=VOC.flatMap(v=>v[2]),x=R(A.filter(y=>(BL?y[0]==BL:y[0]<=BMAX()))),rev=Math.random()<.4;return rev?{p:'Pilih kata Jepang untuk arti ini',big:x[3],a:x[1],note:x[2],o:uq(x[1],()=>R(A)[1])}:{p:'Apa arti kata ini?',big:x[1],a:x[3],note:'Bacaan: '+x[2],say:x[1],o:uq(x[3],()=>R(A)[3])}},
nu:()=>{if(Math.random()<.35){const c=R(CFQ);return{p:'Pilih yang tepat',big:c[0],a:c[1],note:c[3],o:SH(c[2])}}const x=R(NU),t=Math.random()<.5;return{p:'Pilih kata kerja yang tepat (を = transitif, が = intransitif)',big:t?x[0]+'を＿＿。':x[0]+'が＿＿。',a:t?x[1]:x[2],note:x[3]+' = '+x[4],o:SH([x[1],x[2]])}}};
function bq(k){const ks=k=='mix'?['part','qa','dlg','voc','nu']:[k],n=k=='mix'?20:10,qs=[];for(let i=0;i<n;i++){let q;try{q=gen[ks[i%ks.length]]()}catch(e){q=gen.part()}qs.push(q)}
Q={title:'Tata Bahasa & Dialog',pts:5,qs:SH(qs),k:0,r:[],bk:'bunpou()',again:()=>bq(k)};ask()}

