function h2r(s){let o='',g=0;const a=[...s.replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96))];for(let i=0;i<a.length;i++){const c=a[i];if(c=='ー'){o+=o.slice(-1);continue}if(c=='っ'){g=1;continue}let r=KM[c]||c,n=a[i+1];if(n&&'ゃゅょ'.includes(n)){r=r.slice(0,-1);if(!/(sh|ch|j)$/.test(r))r+='y';r+={ゃ:'a',ゅ:'u',ょ:'o'}[n];i++}if(g){r=(r.slice(0,2)=='ch'?'t':r[0])+r;g=0}o+=r}return o}
