function gpk(m){m=m.replace(/\[([^\]]{2,})\]/g,'$1');let h='',r='',pl='',L='';m.replace(/\{([^|]+)\|([^}]+)\}|\[(.)\]|([^{\[]+)/g,(x,a,b,p,t)=>{if(a){h+=`<ruby>${a}<rt>${b}</rt></ruby>`;if(r&&!/ $/.test(r))r+=' ';r+=h2r(b);pl+=a;L='r'}else if(p){h+=p;r=r.trimEnd()+' '+(PM[p]||h2r(p))+' ';pl+=p;L='p'}else{let u=t.replace(/_/g,' ');if(L=='r'&&/^は([、_ ]|$)/.test(t))u='わ'+u.slice(1);u=u.replace(/(では|には|とは|へは|からは|までは|ては)/g,m=>m.slice(0,-1)+'わ');h+=t.replace(/_/g,'');r+=((L=='r'&&/^[がをにでのともは]/.test(u))||/^です/.test(u)?' ':'')+h2r(u);pl+=t.replace(/_/g,'');L='t'}return ''});return{h,r:RO0[pl.replace(/。/g,'')]||r.replace(/。/g,'').replace(/(desu|masu)ka/g,'$1 ka').replace(/(suki|tai)desu/g,'$1 desu').replace(/gaarimasu/g,'ga arimasu').replace(/te(ha|mo)(ikemasen|ii)/g,(x,p,q)=>'te '+(p=='ha'?'wa':'mo')+' '+q).replace(/(\w)nagara/g,'$1 nagara').replace(/hougaii/g,' hou ga ii').replace(/ii(desu)/g,'ii $1').replace(/\s+/g,' ').trim(),pl:pl.replace(/。/g,'')}}
