/* ===== Simulasi berwaktu (simulasi gaya JLPT, bukan skor resmi) ===== */
const TOC={
 N5:{allow:{v:['N5'],g:['N5'],r:['N5']},parts:[['Kosakata dan Kanji',20,12*60],['Tata Bahasa',15,10*60],['Membaca',6,10*60]]},
 N4:{allow:{v:['N5','N4'],g:['N4','N5'],r:['N4','N5']},parts:[['Kosakata dan Kanji',25,15*60],['Tata Bahasa',20,15*60],['Membaca',8,20*60]]},
 N3:{allow:{v:['N3','N4'],g:['N3','N4'],r:['N3','N4']},parts:[['Kosakata dan Kanji',25,15*60],['Tata Bahasa',20,15*60],['Membaca',8,20*60]]}
};
let TO=null;
const toMM=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');
function toOpts(a,pool,key){const o=[a];for(const x of SH(pool)){if(o.length>=4)break;if(x!==a&&!o.includes(x))o.push(x)}return o.length>=3?SH(o):null}
function toVocab(lv,n){
 const ok=TOC[lv].allow.v,mx=lv=='N5'?3:5,pool=W.filter(w=>ok.includes(wl(w[0]))&&w[0].length<=mx&&w[2].length<=40&&!/^(ATM|十分|一日|今日|大人|上手|下手)$/.test(w[0]));
 const arts=pool.map(w=>w[2]),dup=a=>pool.filter(w=>w[2]==a).length>1;
 const out=[];let t=0;
 while(out.length<n&&t++<n*40){
  const w=R(pool),kind=out.length%3,hasK=/[一-鿿]/.test(w[0]);
  if(out.some(q=>q.id==w[0]))continue;
  if(kind==1&&hasK){const o=toOpts(w[1],pool.map(x=>x[1]).filter(x=>Math.abs(x.length-w[1].length)<=3));if(o)out.push({id:w[0],p:'Bagaimana cara membaca kata ini?',t:w[0],o,a:w[1],note:w[0]+' = '+w[1]+' ('+w[2]+')'})}
  else if(kind==2&&hasK&&!dup(w[2])){const o=toOpts(w[0],pool.filter(x=>/[一-鿿]/.test(x[0])).map(x=>x[0]));if(o)out.push({id:w[0],p:'Kata yang tepat untuk arti berikut?',t:w[2],o,a:w[0],note:w[0]+' = '+w[2]+' ('+w[1]+')'})}
  else if(kind==0&&!dup(w[2])){const o=toOpts(w[2],arts);if(o)out.push({id:w[0],p:'Apa arti kata ini?',t:w[0],o,a:w[2],note:w[0]+' ('+w[1]+')'})}
 }
 return out}
function toGram(lv,n){
 const ok=TOC[lv].allow.g,qs=[];
 GR.filter(g=>ok.includes(g[2])).forEach(g=>g[6].forEach(s=>{const[b,a,...r]=s.split('|');qs.push({id:g[0]+b,p:'Pilih yang tepat untuk ＿ ('+g[1]+')',t:b,o:SH([a,...r.slice(0,3)]),a,note:r[3]||''})}));
 const pri=g=>g[0];
 return SH(qs).slice(0,n)}
function toRead(lv,n){
 const ok=TOC[lv].allow.r,tx=SH(BP.map((b,i)=>[b,i]).filter(x=>ok.includes(x[0][5]||'N5'))),qs=[];
 for(const[b]of tx){if(qs.length>=n)break;b[4].forEach(q=>qs.push({id:b[0]+q[0],p:q[0],t:b[1],tr:b[3],read:1,o:SH(q[2]),a:q[1],note:b[3]}))}
 return qs.slice(0,n)}
function toMenu(){tab('latihan');TO=null;S.to=S.to||{};
 $.innerHTML=`<button class="bk" onclick="latihan()">← Kembali</button><h2>Simulasi Ujian JLPT</h2><p class="mu">Simulasi bergaya JLPT dengan batas waktu dan skor untuk setiap bagian. Soal diambil secara acak dari bank soal aplikasi. Level kosakata diperkirakan dari kanji penyusunnya, sehingga beberapa kata bisa terasa lebih mudah atau lebih sulit dari level sebenarnya. Skor ini hanya latihan, bukan skor resmi JLPT, dan belum mencakup bagian menyimak.</p>`+
 ['N5','N4','N3'].map(l=>{const c=TOC[l],b=S.to[l],tot=c.parts.reduce((s,p)=>s+p[1],0),mn=c.parts.reduce((s,p)=>s+p[2],0)/60;return `<button class="main ${l=='N3'?'alt':''}" onclick="toIntro('${l}')"><span>Simulasi ${l}<small>${tot} soal · ${mn} menit · ${c.parts.map(p=>p[0]).join(' / ')}${b?' · terbaik '+b+'%':''}</small></span><span>→</span></button>`}).join('')+
 `<p class="mu"><small>Catatan: bank soal N3 masih terbatas dan belum mencakup seluruh kebutuhan ujian yang sesungguhnya.</small></p>`}
function toIntro(lv){tab('latihan');const c=TOC[lv];
 $.innerHTML=`<button class="bk" onclick="toMenu()">← Kembali</button><h2>Simulasi ${lv}</h2><div class="card">`+c.parts.map((p,i)=>`<div class="row"><span><b>Bagian ${i+1}: ${p[0]}</b></span><small>${p[1]} soal · ${p[2]/60} menit</small></div>`).join('')+`</div><p class="mu">Waktu berjalan per bagian. Kamu boleh pindah soal dan mengubah jawaban selama waktu bagian itu belum habis. Kalau waktu habis, bagian ditutup otomatis. Hasil berupa estimasi skala 180 poin (bagian bahasa 120 + Chōkai 60). Chōkai belum tersedia, jadi hasil menunjukkan poin Chōkai minimal yang kamu perlukan untuk lulus.</p><button class="main" onclick="toStart('${lv}')"><span>Mulai Simulasi</span><span>→</span></button>`}
function toStart(lv){const c=TOC[lv],g=[toVocab,toGram,toRead];
 const parts=c.parts.map((p,i)=>({name:p[0],secs:p[2],qs:g[i](lv,p[1]),ans:[]})).filter(p=>p.qs.length);
 if(!parts.length)return toMenu();
 TO={lv,parts,pi:0,k:0,end:0,t0:Date.now(),late:0};toPart()}
function toPart(msg){tab('latihan');const P=TO.parts[TO.pi];
 $.innerHTML=`<h2>Bagian ${TO.pi+1}/${TO.parts.length}: ${P.name}</h2>${msg?`<div class="fb no"><b>${msg}</b></div>`:''}<p class="mu">${P.qs.length} soal · ${P.secs/60} menit. Waktu mulai berjalan saat kamu menekan tombol.</p><button class="main" onclick="toGo()"><span>Mulai bagian ini</span><span>→</span></button>`}
function toGo(){const P=TO.parts[TO.pi];TO.k=0;TO.fw=0;TO.qc=0;TO.end=Date.now()+P.secs*1000;clearInterval(tm);tm=setInterval(toTick,1000);toShow()}
function toTick(){if(!TO)return;const r=Math.max(0,Math.ceil((TO.end-Date.now())/1000)),e=document.getElementById('tmr');if(e){e.textContent='⏱ '+toMM(r);e.style.color=r<=60?'var(--bad,#c0392b)':''}if(r<=0){clearInterval(tm);toNextPart('Waktu bagian sebelumnya habis.')}}
function toShow(){const P=TO.parts[TO.pi],q=P.qs[TO.k],k=TO.k,n=P.qs.length,done=P.ans.filter(x=>x!=null).length,r=Math.max(0,Math.ceil((TO.end-Date.now())/1000));
 $.innerHTML=`<div class="top"><b>${P.name}</b><span class="mu" id="tmr">⏱ ${toMM(r)}</span></div><div class="bar"><i style="width:${done/n*100}%"></i></div><small class="mu">Bagian ${TO.pi+1}/${TO.parts.length} · soal ${k+1}/${n} · terjawab ${done}</small><p class="mu">${q.p}</p>${q.read?`<div class="card" style="font-size:1.15rem;line-height:1.7">${q.t}</div>`:`<div class="fc" style="font-size:${q.t.length>9?'1.6rem':'2.4rem'}">${q.t}</div>`}<div class="opg">${q.o.map((o,i)=>`<button class="op ${P.ans[k]===o?'sel':''}" onclick="toPick(${i})">${o}</button>`).join('')}</div><div class="acts"><button class="ghost" ${k?'':'disabled'} onclick="toGoTo(${k-1})">‹ Sebelumnya</button><button class="ghost" ${k<n-1?'':'disabled'} onclick="toGoTo(${k+1})">Berikutnya ›</button></div><div class="chips" style="margin-top:8px">${P.qs.map((_,i)=>`<button class="${i==k?'on':''}" style="${P.ans[i]!=null?'font-weight:700':'opacity:.6'}" onclick="toGoTo(${i})">${i+1}</button>`).join('')}</div>${TO.fw?`<div class="fb no"><b>${TO.fw} soal belum dijawab.</b> Ketuk tombol di bawah sekali lagi untuk tetap menyelesaikan bagian ini.</div>`:''}<button class="main alt" onclick="toFinishPart()"><span>${TO.fw?'Ya, selesaikan sekarang':TO.pi<TO.parts.length-1?'Selesai bagian ini':'Selesai dan lihat hasil'}</span><span>→</span></button><button class="ghost" style="width:100%;margin-top:6px" onclick="toQuit()">${TO.qc?'Yakin keluar? Hasil tidak disimpan (ketuk lagi)':'Keluar'}</button>`}
