(function(){
const RM=matchMedia('(prefers-reduced-motion:reduce)').matches,root=document.documentElement;
const css=document.createElement('style');
css.textContent='#kjfire{position:fixed;left:0;top:0;width:100%;height:100%;pointer-events:none;z-index:-1;display:none}'
+'#kjtint{position:fixed;left:0;top:0;width:100%;height:100%;pointer-events:none;z-index:-2;opacity:var(--kjf);background:linear-gradient(to bottom,rgba(var(--kjt1),.7),rgba(var(--kjt2),.05))}'
+':root{--kjf:0;--kjt1:214,84,18;--kjt2:214,84,18;--kjg1:255,106,30;--kjg2:255,176,60}'
+'#app:has(#fb,.fb)>.fc{margin-top:calc(12px + var(--kjf)*30px);box-shadow:0 0 calc(var(--kjf)*38px) calc(var(--kjf)*3px) rgba(var(--kjg1),calc(var(--kjf)*.28)),0 0 calc(var(--kjf)*12px) rgba(var(--kjg2),calc(var(--kjf)*.36))}'
;
document.head.appendChild(css);

const tint=document.createElement('div');tint.id='kjtint';document.body.insertBefore(tint,document.body.firstChild);
const cv=document.createElement('canvas');cv.id='kjfire';document.body.insertBefore(cv,document.body.firstChild);
let DPR=1;
/* ukuran piksel kanvas selalu disamakan dengan ukuran tampilnya (aman di iframe/WebView yang ukurannya berubah) */
function size(){DPR=Math.min(1.5,window.devicePixelRatio||1);const w=cv.clientWidth||innerWidth,h=cv.clientHeight||innerHeight,pw=Math.round(w*DPR),ph=Math.round(h*DPR);if(cv.width!==pw||cv.height!==ph){cv.width=pw;cv.height=ph}}
size();addEventListener('resize',size);if(window.ResizeObserver)new ResizeObserver(size).observe(document.documentElement);

/* ---------- shader api ---------- */
const VS='attribute vec2 a;void main(){gl_Position=vec4(a,0.,1.);}';
const FS=`precision highp float;
uniform vec2 uRes;uniform float uDpr,uT,uI,uSm,uFH,uPur;uniform vec4 uRect,uCut;
float hash(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float vn(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1.,0.)),f.x),mix(hash(i+vec2(0.,1.)),hash(i+vec2(1.,1.)),f.x),f.y);}
float fbm(vec2 p){return .55*vn(p)+.3*vn(p*2.03+7.1)+.15*vn(p*4.1+3.7);}
float rr(vec2 p,vec4 r){vec2 hb=r.zw*.5;vec2 q=abs(p-r.xy-hb)-hb+8.;return length(max(q,0.))+min(max(q.x,q.y),0.)-8.;}
float tongue(float x,float t){float a=.5+.5*sin(x*.085+t*3.1),b=.5+.5*sin(x*.21-t*4.4+1.3),c=.6+.4*sin(x*.021+t*1.2);return pow(a*.65+b*.35,1.4)*c;}
vec3 fcol(float v){vec3 c=mix(vec3(.5,.04,0.),vec3(.93,.2,.03),smoothstep(0.,.25,v));c=mix(c,vec3(1.,.52,.07),smoothstep(.2,.55,v));c=mix(c,vec3(1.,.8,.24),smoothstep(.5,.85,v));return mix(c,vec3(1.,.93,.55),smoothstep(.88,1.,v));}
vec3 pcol(float v){vec3 c=mix(vec3(.16,.02,.36),vec3(.42,.1,.82),smoothstep(0.,.25,v));c=mix(c,vec3(.68,.28,1.),smoothstep(.2,.55,v));c=mix(c,vec3(.86,.58,1.),smoothstep(.5,.85,v));return mix(c,vec3(.97,.88,1.),smoothstep(.88,1.,v));}
float spark(vec2 p,float w){
  if(p.x<0.||p.x>w)return 0.;
  float cw=24.,id=floor(p.x/cw),r1=hash(vec2(id,3.7)),r2=hash(vec2(id,9.1));
  float per=1.5+r2*1.4,tt=uT/per+r1,ph=fract(tt),cyc=floor(tt);
  float act=step(.5,hash(vec2(id,cyc)));
  float x=(id+.2+.6*hash(vec2(id,cyc+1.3)))*cw+sin(uT*2.1+r1*6.28)*7.*ph;
  float y=-ph*(34.+50.*r2)-2.;
  return act*smoothstep(2.3,.2,length(p-vec2(x,y)))*(1.-ph)*(1.-ph);
}
void main(){
  vec2 px=vec2(gl_FragCoord.x,uRes.y-gl_FragCoord.y)/uDpr;
  vec2 p=px-uRect.xy;float w=uRect.z,h=uRect.w;
  vec2 hb=vec2(w,h)*.5,c=p-hb,q=abs(c)-hb+8.;
  float sd=length(max(q,0.))+min(max(q.x,q.y),0.)-8.,o=max(sd,0.);
  if(sd<-1.||o>110.){gl_FragColor=vec4(0.);return;}
  vec2 nr=sign(c)*max(q,0.);float nl=length(nr);nr=nl>.001?nr/nl:vec2(0.,-1.);
  float up=clamp(-nr.y,0.,1.),sideF=clamp(abs(nr.x),0.,1.)*(1.-clamp(p.y/h,0.,1.));
  float reach=uFH*(.16+.84*up+.34*sideF*(1.-up))*(1.-.85*clamp(nr.y,0.,1.));
  float tg=tongue(clamp(p.x,-14.,w+14.),uT);
  float H=max(reach*(.28+.72*tg)*(.25+.75*uI),1.),u=o/H;
  vec2 np=vec2(p.x*.05,p.y*.055+uT*2.6);
  np.x+=(vn(np*.7+vec2(3.1,uT*.4))-.5)*1.2*clamp(u,0.,1.);
  float n=fbm(np),f=clamp(1.-u,0.,1.);
  float v=clamp(f*1.1*mix(1.,n*1.7,clamp(u*1.2,0.,1.)),0.,1.);
  float fl=clamp(uI*1.35,0.,1.),a=smoothstep(.03,.42,v)*fl;
  float t1=clamp(uPur,0.,1.),t2=clamp(uPur-1.,0.,1.);
  float pw=t1*mix(1.-smoothstep(.22,.7,v),1.,t2);
  vec3 col=mix(fcol(v),pcol(v),pw);
  /* asap tipis saat api padam */
  float ab=-p.y;
  float sn=fbm(vec2(p.x*.03,p.y*.03+uT*.5)*2.);
  float sm=uSm*smoothstep(-4.,12.,ab)*(1.-smoothstep(14.,96.,ab))*smoothstep(.38,.78,sn)*smoothstep(-10.,10.,p.x)*smoothstep(-10.,10.,w-p.x);
  vec3 smk=vec3(.5,.47,.45);float sa=sm*.26;
  /* halo hangat + bara */
  float halo=exp(-o*.055)*(.35+.65*up)*.2*fl;
  float sp=0.;if(ab>-6.)sp=spark(p,w)*fl;
  vec3 pm=smk*sa;float al=sa;
  pm=pm*(1.-a)+col*a;al=al*(1.-a)+a;
  pm=pm*(1.-halo)+mix(vec3(1.,.42,.08),vec3(.62,.26,1.),t1*.55+t2*.45)*halo;al=al*(1.-halo)+halo;
  pm+=mix(vec3(1.,.78,.34),vec3(.85,.66,1.),t1*.5+t2*.5)*sp;al=min(1.,al+sp);
  float cm=smoothstep(0.,1.5,rr(px,uCut));
  gl_FragColor=vec4(pm*cm,al*cm);
}`;
let gl=null,prog=null,U={};
(function(){
  try{
    gl=cv.getContext('webgl',{alpha:true,premultipliedAlpha:true,antialias:false,depth:false,stencil:false,powerPreference:'low-power'});
    if(!gl)return;
    const sh=(t,s)=>{const o=gl.createShader(t);gl.shaderSource(o,s);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(o));return o};
    prog=gl.createProgram();gl.attachShader(prog,sh(gl.VERTEX_SHADER,VS));gl.attachShader(prog,sh(gl.FRAGMENT_SHADER,FS));gl.linkProgram(prog);
    if(!gl.getProgramParameter(prog,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(prog));
    gl.useProgram(prog);
    const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);
    const l=gl.getAttribLocation(prog,'a');gl.enableVertexAttribArray(l);gl.vertexAttribPointer(l,2,gl.FLOAT,false,0,0);
    ['uRes','uDpr','uT','uI','uSm','uFH','uPur','uRect','uCut'].forEach(k=>U[k]=gl.getUniformLocation(prog,k));
    gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE_MINUS_SRC_ALPHA);
    cv.addEventListener('webglcontextlost',e=>{e.preventDefault();gl=null});
  }catch(e){console.error('kjfire:',e.message);gl=null}
})();

/* ---------- keadaan api ---------- */
let I=0,V=0,Sm=0,Pu=0,pT=0,lastPu=-1,last=0,run=false,time=Math.random()*50,R={x:0,y:0,w:300,h:180},cut=null;
const PADL=40,PADT=120,PADB=44,FH=76;

const OR=[214,84,18],PU=[118,48,222],GO=[255,106,30],GP=[170,80,255],GO2=[255,176,60],GP2=[210,150,255];
const mx=(a,b,t)=>a.map((x,i)=>Math.round(x+(b[i]-x)*t));
function streakNow(){let s=0;for(let i=Q.r.length-1;i>=0&&Q.r[i];i--)s++;return s}
function setColors(){
  const t1=Math.min(1,Pu),t2=Math.max(0,Pu-1),g=t1*.6+t2*.4;
  root.style.setProperty('--kjt1',mx(OR,PU,t1).join(','));root.style.setProperty('--kjt2',mx(OR,PU,t2).join(','));
  root.style.setProperty('--kjg1',mx(GO,GP,g).join(','));root.style.setProperty('--kjg2',mx(GO2,GP2,g).join(','));
}
/* kartu soal di layar kuis (api tetap mengikuti kartu selama memudar) */
function quizCard(){
  if(typeof Q==='undefined'||!Q)return null;
  const fc=$.querySelector(':scope>.fc'),b=$.querySelector(':scope>.top>b');
  if(!fc||!b)return null;
  const t=b.textContent.trim();
  return(t===String(Q.title).trim()||t==='Tinjau soal')?fc:null;
}
/* posisi kartu tanpa transform animasi, supaya api tidak ikut bergeser saat kartu meluncur */
function layout(el){
  const r=el.getBoundingClientRect();let ex=0,ey=0,sx=1,sy=1;
  const tr=getComputedStyle(el).transform;
  if(tr&&tr!=='none'){try{const m=new DOMMatrixReadOnly(tr);ex=m.e;ey=m.f;sx=m.a||1;sy=m.d||1}catch(_){}}
  const w=r.width/sx,h=r.height/sy;
  return{x:r.left+r.width/2-ex-w/2,y:r.top+r.height/2-ey-h/2,w,h};
}
function draw(){
  const W=cv.width,Hh=cv.height;
  gl.viewport(0,0,W,Hh);gl.disable(gl.SCISSOR_TEST);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);
  if(I<.003)return;
  const sc=W/(cv.clientWidth||innerWidth),x0=Math.max(0,Math.floor((R.x-PADL)*sc)),x1=Math.min(W,Math.ceil((R.x+R.w+PADL)*sc)),y0=Math.max(0,Math.floor((R.y-PADT)*sc)),y1=Math.min(Hh,Math.ceil((R.y+R.h+PADB)*sc));
  if(x1<=x0||y1<=y0)return;
  gl.enable(gl.SCISSOR_TEST);gl.scissor(x0,Hh-y1,x1-x0,y1-y0);
  gl.uniform2f(U.uRes,W,Hh);gl.uniform1f(U.uDpr,W/(cv.clientWidth||innerWidth));gl.uniform1f(U.uT,time);gl.uniform1f(U.uI,I);gl.uniform1f(U.uSm,Sm*4*I*(1-I));gl.uniform1f(U.uFH,FH);gl.uniform1f(U.uPur,Pu);
  gl.uniform4f(U.uRect,R.x,R.y,R.w,R.h);
  if(cut)gl.uniform4f(U.uCut,cut.x,cut.y,cut.w,cut.h);else gl.uniform4f(U.uCut,-1e4,-1e4,1,1);
  gl.drawArrays(gl.TRIANGLES,0,3);
}
let lastFv='';
function tick(ts){
  size();
  let dt=(ts-last)/1000;last=ts;if(!(dt>0))dt=.016;if(dt>.033)dt=.033;time+=dt;
  const card=quizCard(),tgt=(card&&Q.hot)?1:0;
  /* ikuti kartu dengan halus (kartu bisa berganti tinggi antar soal) */
  if(card){const r=layout(card);cut=r;if(I<.01&&!V){R={x:r.x,y:r.y,w:r.w,h:r.h}}else{const k=1-Math.exp(-dt/.07);R.x+=(r.x-R.x)*k;R.y+=(r.y-R.y)*k;R.w+=(r.w-R.w)*k;R.h+=(r.h-R.h)*k}}else cut={x:R.x,y:R.y,w:R.w,h:R.h};
  /* intensitas: pegas teredam kritis; menyala pelan, padam sedikit lebih cepat */
  const wn=tgt?5.2:(card?6.8:9.5);V+=(wn*wn*(tgt-I)-2*wn*V)*dt;I+=V*dt;if(I<0){I=0;V=0}if(I>1){I=1;if(V>0)V=0}
  Sm+=((tgt?0:1)-Sm)*(1-Math.exp(-dt/.12));
  /* tingkat warna: 0 oranye, 1 campur ungu (streak 25-39), 2 ungu penuh (40+). Tetap beku saat api padam. */
  if(tgt){const st=streakNow();pT=st>=40?2:st>=25?1:0}
  if(I<.01&&!V)Pu=pT;else Pu+=(pT-Pu)*(1-Math.exp(-dt/.7));
  if(Math.abs(Pu-lastPu)>.002){lastPu=Pu;setColors()}
  {const fv=(I*I*(3-2*I)).toFixed(3);if(fv!==lastFv){lastFv=fv;root.style.setProperty('--kjf',fv)}}
  if(gl&&!RM)draw();
  if(!tgt&&I<.004){run=false;I=0;V=0;cut=null;if(gl){gl.disable(gl.SCISSOR_TEST);gl.clear(gl.COLOR_BUFFER_BIT)}cv.style.display='none';lastFv='0';root.style.setProperty('--kjf','0');return}
  requestAnimationFrame(tick);
}
window.kjFireKick=function(){if(run)return;run=true;cv.style.display='block';size();last=performance.now();requestAnimationFrame(tick)};

/* ===== Penanda streak: kapan api menyala/padam (api digambar di atas) ===== */
if(typeof mark==='function'){const o=mark;mark=function(ok){const r=o.apply(this,arguments);try{
  let s=0;for(let i=Q.r.length-1;i>=0&&Q.r[i];i--)s++;
  if(!ok)Q.hot=false;else if(s>=5)Q.hot=true;
  const f=document.querySelector('#app .fc');
  if(ok&&s>=3&&f){const o2=f.querySelector('.strk');if(o2)o2.remove();f.insertAdjacentHTML('beforeend','<span class="strk">🔥 x'+s+'</span>')}
  window.kjFireKick()}catch(e){}return r}}
})();


