DKB=[['<u>大人</u>は千円です。','おとな',['だいにん','おおひと','たいじん']],['<u>一日中</u>雨でした。','いちにちじゅう',['ついたちじゅう','いちじつじゅう','ひとひじゅう']],['<u>上手</u>に話せます。','じょうず',['じょうしゅ','うえて','あがて']],['<u>一人</u>で行きます。','ひとり',['いちじん','ひとにん','いちひと']],['<u>今朝</u>は早く起きました。','けさ',['こんちょう','いまあさ','きんあさ']],['<u>八百屋</u>で野菜を買います。','やおや',['はちひゃくや','やおく','はっぴゃくや']]];
const DKP=(a,n)=>SH([...a]).slice(0,n),
dkD=(a,mut,pool,n=3)=>{const s=new Set(mut.filter(x=>x&&x!==a));for(const x of SH(pool)){if(s.size>=n)break;if(x!==a)s.add(x)}return[...s].slice(0,n)},
dkKS={ゃ:'や',ゅ:'ゆ',ょ:'よ'},dkKW={ゃ:'ゅ',ゅ:'ょ',ょ:'ゃ'},
dkMK=k=>[k.replace(/っ/,'つ'),k.replace(/っ/,''),k.replace(/[ゃゅょ]/,m=>dkKS[m]),k.replace(/[ゃゅょ]/,m=>dkKW[m]),k.replace(/[ゃゅょ]/,''),k.replace(/っ(.)/,'$1っ')],
dkYV=/(sh|ch|j|ky|ny|ry|gy|hy|by|py|my)([auo])/,
dkMR=r=>[r.replace(/([kstp])\1/,'$1'),r.replace(dkYV,(m,a,b)=>a+'auo'[('auo'.indexOf(b)+1)%3]),r.replace(dkYV,(m,a,b)=>a+'auo'[('auo'.indexOf(b)+2)%3])],
dkQ=(big,a,wrong,p,note)=>({p,big,a,note,o:SH([a,...wrong])}),
dkRd=(it,pool,mut)=>dkQ(it[0],it[1],dkD(it[1],mut?mut(it[1]):[],pool.map(x=>x[1])),'Bagaimana cara membacanya?',it[0]+' = '+it[1]+(it[2]?' ('+it[2]+')':'')),
dkSet=(t,n,qs)=>{Q={title:t,pts:5,qs:SH(qs),k:0,r:[],bk:'belajar()',again:()=>dkLatih(n)};ask()};
function dkLatih(n){
 if(n==0){const w=DKP(DKW,6);dkSet('Yōon dan Sokuon',0,[...DKP(DKY,3).map(x=>dkRd([x[0],x[1]],DKY,null)),...w.slice(0,3).map(x=>dkRd(x,DKW,dkMR)),...w.slice(3).map(x=>dkQ(x[1]+' ('+x[2]+')',x[0],dkD(x[0],dkMK(x[0]),DKW.map(y=>y[0])),'Pilih tulisan kana yang benar',x[0]+' = '+x[1]))])}
 else if(n==1){dkSet('Counters',1,[...DKP(DKC,5).map(c=>dkQ(c[0],c[1],dkD(c[1],[],DKC.map(x=>x[1])),'Satuan hitung apa yang dipakai?',c[1]+' untuk: '+c[0])),...DKP(DKR,5).map(x=>dkRd(x,DKR,null))])}
 else if(n==2){dkSet('Tanggal dan Waktu',2,[...DKP(DKT,4).map(x=>dkRd(x,DKT,null)),...DKP(DKM,2).map(x=>dkRd(x,DKM,null)),...DKP(DKH,1).map(x=>dkRd(x,DKH,null)),...DKP(DKJ,3).map(x=>dkRd(x,DKJ,null))])}
 else{dkSet('Soal Konteks N4',3,[...DKP(DKX,4).map(x=>dkQ(x[0],x[1],x[2],'Pilih kata yang melengkapi bagian rumpang','Jawaban: '+x[1])),...DKP(DKS,2).map(x=>dkQ(x[0],x[1],x[2],'Pilih kalimat dengan arti yang paling dekat','Jawaban: '+x[1])),...DKP(DKK,3).map(x=>dkQ(x[0],x[1],x[2],'Pilih kanji yang benar untuk bagian dalam 【 】','Jawaban: '+x[1])),...DKP(DKB,3).map(x=>dkQ(x[0],x[1],x[2],'Bagaimana membaca bagian bergaris bawah menurut konteks?','Jawaban: '+x[1]))])}
}
{const ib0=itemsBel;itemsBel=function(k){const a=ib0(k);if(k==='latihan')a.push(['Bunyi Yōon dan Sokuon (N4)','Bunyi kecil ゃゅょ dan っ','dkLatih(0)'],['Penghitung (Counters) N4','Satuan hitung 枚 本 匹 台 人','dkLatih(1)'],['Tanggal dan Waktu (N4)','ついたち, ふつか, bulan, hari, dan jam','dkLatih(2)'],['Soal Konteks N4','Cloze, sinonim, tulis kanji, baca konteks','dkLatih(3)']);return a}}


