let CK=null;const CKT={task:'Pemahaman Tugas (課題理解)',point:'Pemahaman Poin (ポイント理解)',quick:'Respons Cepat (即時応答)',sum:'Pemahaman Isi (概要理解)'},
ckVo=()=>{try{return(speechSynthesis.getVoices()||[]).filter(x=>/^ja/i.test(x.lang))}catch(e){return[]}},
ckStop=()=>{try{speechSynthesis.cancel()}catch(e){}},
ckOf=()=>TO&&TO.lv=='N4'&&S.ck?S.ck:null;
function ckPlay(){if(!CK)return;const q=CK.qs[CK.k],vs=ckVo();ckStop();CK.pl=(CK.pl||0)+1;const b=document.getElementById('ckn');if(b)b.textContent='Diputar '+CK.pl+'×';
 setTimeout(()=>{q.s.forEach(([sp,tx])=>{try{const u=new SpeechSynthesisUtterance(tx);u.lang='ja-JP';u.rate=Math.max(.1,.9*CK.spd);u.pitch=sp=='F'?1.25:sp=='M'?.8:1;const v=vs.length>1&&sp=='M'?vs[1]:vs[0];if(v)u.voice=v;speechSynthesis.speak(u)}catch(e){}})},60)}
function ckSpd(v,el){CK.spd=v;el.parentNode.querySelectorAll('button').forEach(b=>b.classList.remove('on'));el.classList.add('on');ckPlay()}
function ckMenu(){tab('latihan');const l=S.ck;$.innerHTML=`<button class="bk" onclick="ckStop();belajar()">← Kembali</button><h2>Menyimak JLPT N4 (Chōkai)</h2><p class="mu">Latihan mendengarkan gaya JLPT N4: pemahaman tugas, pemahaman poin, pemahaman isi, ungkapan situasi, dan respons cepat. Dengarkan audio, lalu pilih jawaban. Kamu bisa memutar ulang dan memperlambat suara (0,75× atau 0,5×).</p><div class="card"><div class="row"><span>Bobot di ujian</span><small>60 dari 180 poin · minimal 19</small></div><div class="row"><span>Sesi terakhir</span><small>${l?l.ok+'/'+l.n+' benar · estimasi '+l.sc+'/60':'belum ada'}</small></div></div><div class="fb no"><small>Suara dibuat oleh TTS bawaan perangkat. Kualitas pelafalan bergantung pada hardware dan browser kamu, jadi bisa berbeda dari rekaman ujian asli.${ckVo().length?'':' Suara bahasa Jepang belum terdeteksi di perangkatmu; instal suara Jepang di pengaturan perangkat jika audio tidak keluar.'}</small></div><button class="main" onclick="ckStart()"><span>Mulai (10 soal)</span><span>→</span></button><button class="main alt" onclick="toMenu()"><span>Simulasi N4 (bagian bahasa)<small>Skor Chōkai terakhir ikut dihitung ke total 180</small></span><span>→</span></button>`}
function ckStart(){CK={qs:SH(CKB).slice(0,10).map(q=>({...q,o:SH(q.o)})),k:0,r:[],spd:1,pl:0};ckShow()}
function ckShow(){ckStop();const q=CK.qs[CK.k],n=CK.qs.length;CK.pl=0;CK.done=false;tab('latihan');
 $.innerHTML=`<button class="bk" onclick="ckStop();ckMenu()">← Keluar</button><div class="top"><b>Chōkai N4</b><span class="mu">${CK.k+1} / ${n}</span></div><div class="bar"><i style="width:${CK.k/n*100}%"></i></div><p class="mu"><small>${CKT[q.t]}</small></p><div class="card" style="text-align:center"><button class="main" style="justify-content:center" onclick="ckPlay()"><span>🎧 Putar / putar ulang</span></button><small id="ckn" class="mu">Belum diputar</small><div class="chips">${[[1,'1×'],[.75,'0,75×'],[.5,'0,5×']].map(([v,l])=>`<button class="${CK.spd==v?'on':''}" onclick="ckSpd(${v},this)">${l}</button>`).join('')}</div><small class="mu">Kualitas suara tergantung perangkat dan browser kamu.</small></div><p><b>${q.p}</b></p><div class="opg">${q.o.map((x,i)=>`<button class="op" onclick="ckAns(${i},this)">${x}</button>`).join('')}</div><div id="ckfb"></div>`}
function ckAns(i,el){if(CK.done)return;CK.done=true;ckStop();const q=CK.qs[CK.k],ok=q.o[i]===q.a,last=CK.k+1>=CK.qs.length;CK.r.push(ok);
 el.parentNode.querySelectorAll('button').forEach(b=>{if(b.textContent===q.a){b.style.borderColor='var(--ok)';b.style.background='var(--okb)'}});if(!ok){el.style.borderColor='var(--ng)';el.style.background='var(--ngb)'}
 document.getElementById('ckfb').innerHTML=`<div class="fb ${ok?'ok':'no'}"><b>${ok?'Benar':'Salah'}</b><br><small>Jawaban: ${q.a}</small></div><div class="hist"><small class="mu">Naskah</small><br>${q.s.map(x=>(x[0]?x[0]+': ':'')+x[1]).join('<br>')}<br><small>${q.tr}</small></div><button class="main" onclick="${last?'ckEnd()':'ckNext()'}"><span>${last?'Lihat hasil':'Lanjut'}</span><span>→</span></button>`}
function ckNext(){CK.k++;ckShow()}
function ckEnd(){ckStop();const n=CK.qs.length,ok=CK.r.filter(Boolean).length,sc=Math.round(ok/n*60),pass=sc>=19,by={};CK.qs.forEach((q,i)=>{const b=by[q.t]=by[q.t]||[0,0];b[1]++;if(CK.r[i])b[0]++});
 S.ck={sc,ok,n,d:Date.now()};S.hist.unshift({t:'Chōkai N4',ok,n,p:pass?30:5,d:Date.now()});S.xp+=pass?30:5;save();
 $.innerHTML=`<button class="bk" onclick="ckMenu()">← Kembali</button><h2>Hasil Chōkai N4</h2><div class="score"><b>${sc}/60</b> <small>estimasi poin</small> · ${ok} benar dari ${n}</div><div class="fb ${pass?'ok':'no'}"><b>${pass?'Di atas batas minimal bagian Chōkai (19/60).':'Di bawah batas minimal bagian Chōkai (19/60).'}</b></div><div class="hist">${Object.entries(by).map(([k,v])=>`<div class="row"><span>${CKT[k]}</span><small>${v[0]}/${v[1]}</small></div>`).join('')}</div><p class="mu"><small>Estimasi dari persentase benar; skor resmi JLPT memakai penyekalaan statistik.</small></p><button class="main" onclick="ckStart(CK&&CK.n)"><span>Coba lagi</span><span>→</span></button><button class="main alt" onclick="toMenu()"><span>Lanjut ke Simulasi N4</span><span>→</span></button>`}
{const ib1=itemsBel;itemsBel=function(k){const a=ib1(k);if(k==='latihan')a.push(['Menyimak JLPT N4 (Chōkai)','Audio gaya JLPT dengan putar ulang dan kecepatan lambat','ckMenu()']);return a}}


