{const ib2=itemsBel;itemsBel=function(k){const a=ib2(k);if(k==='latihan'){const p=gsPlan();a.push(['Ulangan Tata Bahasa (SRS)',p.due.length+' jatuh tempo · '+p.nw.length+' baru · '+p.hafal+'/'+p.tot+' hafal','gsStart()'],['Dikte Kalimat 🎧','Dengar kalimat, ketik dalam hiragana atau kanji','dtStart()'],...RP.map((r,i)=>['Roleplay: '+r[0],'Percakapan dengan pilihan jawaban dan umpan balik','rpStart('+i+')']))}return a}}


