/* --- normalisasi cara baca: romaji (si/shi, ti/chi, hu/fu), hiragana, katakana, apostrof n'y --- */
const rPre=s=>String(s).toLowerCase().replace(/ō/g,'ou').replace(/ū/g,'uu').replace(/n[-'’\s]+(?=[aiueoy])/g,'#').replace(/[\s\-'’.,・、。]/g,'');
