const toHira=s=>String(s).replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-96)).replace(/[\s・、。\-]/g,'');
const hasKana=s=>/[぀-ヿ]/.test(s);
