function ripple(el,e){const r=el.getBoundingClientRect(),d=Math.max(r.width,r.height)*2,s=document.createElement('span'),cx=e.detail?e.clientX-r.left:r.width/2,cy=e.detail?e.clientY-r.top:r.height/2;
 s.className='kj-rp';s.style.cssText=`width:${d}px;height:${d}px;left:${cx-d/2}px;top:${cy-d/2}px`;el.appendChild(s);
 const a=s.animate([{transform:'scale(0)',opacity:.2},{transform:'scale(1)',opacity:0}],{duration:500,easing:'ease-out'});a.onfinish=a.oncancel=()=>s.remove()}
function pop(el){if(el.__kp)el.__kp.cancel();el.__kp=el.animate([{transform:'scale(1)'},{transform:'scale(.95)',offset:.35},{transform:'scale(1.025)',offset:.7},{transform:'scale(1)'}],{duration:300,easing:'ease-out'})}
